    "question": "日本農林規格（JAS）に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　JASは「日本農林規格等に関する法律」に基づく国家規格であり、飲食料品や農林水産物などの品質の改善、取引の円滑化等のほか、消費者の合理的な選択の機会の拡大を図り、もって農林水産業及びその関連産業の健全な発展と消費者の利益の保護に寄与することを目的としている。\nB　JASに定められる基準は、飲食料品や農林水産物などの成分や性能が対象となるほか、栽培管理や飼養管理などの生産行程及び保管・輸送管理などの流通行程、成分の測定方法などの試験方法も対象となる。また、観賞用の植物・魚や、真珠、漆などもJASの制定対象となる。\nC　JASは、「日本農林規格等に関する法律」の法目的を達成するため必要があると認められるときに、農林水産大臣又は農林水産大臣からの委任を受けた都道府県知事によって制定される。さらに、JASの改正は、規格内容に関連する民間団体に委任されている。\nD　JASには特級、上級、標準の三つの等級があり、どの等級に該当するかについては含有成分の多少及び製造数量（希少性）によって決まっている。さらに、近年多様化する食の嗜好に対応するため、令和5（2023）年度末時点で、「ベジタリアン又はヴィーガンに適した加工食品」、「細胞性食品」を対象としたJASが制定されている。",
