    "question": "農産物の国際交渉や国際協力に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　世界共通の貿易ルールづくり等が行われるWTO（世界貿易機関）において、これまで数次にわたる貿易自由化交渉が行われてきた。2001年に開始されたウルグアイ・ラウンド交渉においては、途上国と先進国の溝が埋まらずに決裂し、現在はドーハ・ラウンド交渉が行われている。\nB　TPP（環太平洋パートナーシップ）協定については、2016年に署名された後、米国が離脱したが、米国を除く11か国の間で協議を行い、CPTPP（環太平洋パートナーシップに関する包括的及び先進的な協定）が2018年に署名された。\nC　日EU・EPA（日EU経済連携協定）は、2013年に交渉が開始されたが、交渉の途中で英国がEUから離脱した。このためEU域内の交渉に向けた手続きに時間を要しており、現在も交渉が継続されている。\nD　我が国は、東アジア地域における食料安全保障の強化と貧困の撲滅を目的とした米の備蓄制度である「ASEAN＋3緊急米備蓄」（APTERR）において、現物備蓄事業への拠出や事務局への日本人専門家の派遣など、積極的に支援している。",
