    "difficulty": 3,
    "question": "地球温暖化に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　地球温暖化は、大気中の水蒸気や温室効果ガス（GHG）が地表面から放射された赤外線を吸収することによって起こる。GHGとして知られる二酸化炭素、メタン、一酸化二窒素のうち、地球温暖化係数が最も高いものは一酸化二窒素である。\nB　2020年度における我が国のGHGの総排出量を二酸化炭素に換算すると11億5千万トンであり、このうちの約4％が農林水産分野から排出されたと見積もられている。農林水産分野で排出されたGHGのうち約37％が二酸化炭素、約44％がメタン、約19％が一酸化二窒素であった。\nC　IPCCは1988年に設立された国連の政府間組織であり、日本語での名称は「地球温暖化に関する政府間パネル」である。IPCCでは、地球温暖化に関連する科学的、技術的、社会・経済的情報を取りまとめて評価し、得られた知見に基づいて各国政府に具体的な政策を提示している。\nD　2021年のIPCC第6次報告書によると、2011～2020年の世界の地表面温度（地上の平均気温）は、1850～1900年と比較して約3 ℃高くなった。また、同報告書では「人為起源の温室効果ガスは気候変化を生じさせるおそれがある」と述べられている。",
