    "question": "我が国の畜産の状況に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　令和4（2022）年の農業総産出額を部門別にみると、畜産の割合が約50％と最も多く、次いで米の割合が約24％となっている。畜産の産出額の内訳をみると、和牛の輸出量の増加等を背景に、肉用牛が最も多く、次いで、豚、鶏となっている。\nB　我が国全体の生乳の生産量は、乳用牛の飼養頭数や一頭当たりの乳量の増加により増加傾向で推移してきたが、令和4年度は需給緩和等を背景に減少に転じた。また、都府県の生乳生産量は、令和元（2019）年度以降、毎年減少しており、令和4年度は北海道の生産量の約50％となっている。\nC　豚肉について、令和5（2023）年度の部分肉ベースの国別輸入量は、米国が最も多く、次いでカナダ、スペインとなっている。また、豚肉の重量ベースでの自給率については、近年、50％前後で推移しているが、輸入飼料の利用が多いことから、飼料自給率を考慮した自給率は10％以下となっている。\nD　飼料穀物のうち、とうもろこしについて、令和5年度の国別の輸入量は、米国、ブラジルが多く、令和4年度は、米国とブラジルで全体の輸入量の約90％を占めている。また、平成26（2013）年度から令和4年度にかけての飼料自給率の推移をみると、粗飼料は76～78％、濃厚飼料は12～14％と、大きな変化はない状況となっている。",
