    "difficulty": 3,
    "question": "海業に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　令和4（2022）年3月に閣議決定された水産基本計画及び漁港漁場整備長期計画において、漁港を海業に利活用するための仕組みを検討していくことが明記された。そして、水産庁は、地域の理解と協力の下、水産物の消費増進や交流促進など、地域の水産業を活性化する海業の取組を促進することとしている。\nB　海業とは、海や漁村の地域資源の価値や魅力を活用する事業であって、国内外からの多様なニーズに応えることにより、地域のにぎわいや所得と雇用を生み出すことが期待されるものをいう。主に直売所やレストラン、体験型イベントを指し、漁業や養殖業は海業に含まれない。また、漁村での宿泊業も渚泊に分類され、海業には含まれない。\nC　漁港における海業の推進に向けて、漁港漁場整備法の一部が改正され、法律名も「漁港及び漁場の整備等に関する法律」へと改められた。この改正により、漁港管理者の認定を受けて漁港施設等活用事業を実施する者に対し、行政財産である漁港施設の最大30年の貸付けなどが可能となった。\nD　水産庁は、5年間でおおむね1,000件の漁港における新たな海業等の取組実施に向け、「海業振興モデル地区」及び「海業の推進に取り組む地区」を決定した。「海業振興モデル地区」は、令和5（2023）年3月に、66地区が選ばれた。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "A、D",
      "エ": "B、D",
      "オ": "C、D"
    },
