    "difficulty": 3,
    "question": "HACCP（Hazard Analysis and Critical Control Point）に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　HACCPとは、食品等事業者自らが、食中毒菌汚染や異物混入等の危害要因を除去又は低減させるために特に重要な工程を管理し、製品の安全性を確保しようとする衛生管理の手法である。HACCPシステムを適切に機能させるためには、従業員の教育訓練などの一般衛生管理を適切に実施する必要がある。\nB　令和3（2021）年6月から、全ての食品等事業者はHACCPに沿った衛生管理の実施が必要となったが、学校や病院等の集団給食施設は食品等事業者に含まれないため、HACCPに沿った衛生管理を実施しなくてもよい。衛生管理の実施状況に不備がある場合、各地方公共団体の保健所から直ちに営業停止等の行政処分が下されることとなっている。\nC　HACCPにおいて、人の健康に被害を及ぼす原因となる物質等を危害要因といい、生物学的、化学的、物理的要因に分けられる。HACCPに基づいた衛生管理を実施する食品等事業者は、あらゆる工程において発生するおそれのある危害要因をあらかじめ分析し、それを防除するための対策を講じる必要がある。\nD　大規模事業者等がHACCPシステムを導入するためには、国際標準化機構（ISO）の7原則を組み込んだ12の手順に沿って、施設・製品ごとにプランを構築しなければならない。このシステムは、最終製品のサンプル検査によって、効率的な衛生管理を行うことを基本としている。",
