    "difficulty": 3,
    "question": "水産業をめぐる国際情勢に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年度 水産白書（令和6年6月11日公表）」による。\n\nA　水産物は国際取引に仕向けられる割合の高い国際商材であり、世界の漁業・養殖業生産量の7割以上が輸出に仕向けられている。令和3（2021）年における水産物輸出量を国・地域別にみると、それぞれ多い順に、輸出量ではEU・英国、中国、日本であり、輸入量ではEU・英国、中国、米国である。\nB　令和4（2022）年6月に開催された第12回世界貿易機関（WTO）閣僚会議において、WTO協定改正議定書が採択された。同協定は、IUU＊漁業につながる補助金の禁止、乱獲された資源の枯渇を助長する補助金の原則禁止等を内容とする漁業補助金協定が盛り込まれており、WTO加盟国の3分の2が締結した時に発効する。\nC　国際連合食糧農業機構（FAO）がまとめた、世界の海洋水産資源の状況をみると、令和元（2019）年では、適正レベルの上限まで漁獲されている状態の資源の割合は25％となっている。また、適正レベルまで漁獲されておらず、生産量を増大させる余地のある資源の割合は65％、過剰利用状態の資源の割合は10％となっている。\nD　IUU漁業の抑制・根絶に向けた取組が国際的に進められている。FAOは各国の捜査機関に対して「赤手配書」を発行し、IUU漁業への関与が確認された船舶への注意を促している。また、いくつかの地域漁業管理機関においては、水産エコラベルの認証制度によりIUU漁業由来の漁獲物の国際的な流通の防止を行っている。\n\n＊ Illegal, Unreported and Unregulated",
