      "ウ": "50％と自然的条件は合っている。改正法は2020年12月施行で、MSYは持続的に採捕可能な数量の最大値である。",
      "エ": "ロジスティック型の余剰生産量は資源量が環境収容力の半分に達したとき最大で、その点に対応する漁獲率は内的自然増加率の半分となる。2020年12月施行の改正漁業法では、現在と予測される将来の自然的条件の下で持続的に採捕可能な数量の最大値と定義する。",
      "オ": "古典的モデルの50％と改正法の施行時期、最大値は合う。法が考慮する条件は経済的条件ではなく自然的条件である。"
