    "question": "次は、沿岸域に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n沿岸域とは、水深［A］の大陸棚縁辺により外洋域と区分される陸側の海域のことである。沿岸域は水深が浅く、河川を通して陸起源の物質が流入する特徴を有し、生物活動が活発で物質の動きが著しい海域である。\n\n内湾に位置する河口域では、沖へ向かって上層で［B］が流出し、下層で湾内底層の水が流入する鉛直循環である［C］が卓越する。湾内底層の栄養塩類が豊富な海域では、［C］が河口域表層への栄養塩類の供給源として機能する。一方で、湾内底層が無酸素状態の還元的な環境にある海域では、［C］や陸から海へ向かう強い風により底層の［D］が表層へ運ばれ、海水が変色する［E］が発生する。［E］は酸素をほとんど含まないため、魚介類をへい死させることがある。",
