      "イ": "大気中には作物の成長に必須であるCO₂が含まれる一方で、作物の成長を阻害する物質も含まれる。光化学オキシダントの一つであるオゾンは主にSOₓと呼ばれる硫黄酸化物から生成され、作物の成長を阻害する。オゾンに対する感受性は植物種によって異なり、タバコやアサガオはオゾンに対する耐性が比較的高いことが知られている。",
