      "オ": "作物の栽培は環境負荷の軽減に配慮して行われる必要がある。農林水産省の「特別栽培農産物に係る表示ガイドライン」（平成19年3月改正）によると、特別栽培農産物とは、生産される地域の慣行レベルと比較して、節減対象農薬の使用回数が50％以下で、かつ化学肥料の窒素成分量が50％以下で栽培された農産物のことである。"
