      "イ": "ブドウの「トムソンシードレス」やカキの「平核無」、ウンシュウミカンなどのように、受精した胚の発育が途中で停止して結実することを偽単為結果という。ブドウのジベレリン処理では、人為的に偽単為結果を誘発している。",
      "ウ": "ブドウの「デラウェア」の無核果生産では、開花前と開花後にジベレリン処理を行う。開花前の処理は花穂伸長を、開花後の処理は無核化と果粒肥大を目的としている。ジベレリン処理により成熟期は遅くなる。",
      "エ": "イチジクは花の種類や受粉の必要性などから、サンペドロ系、普通系などに分類される。我が国の主要品種である「桝井ドーフィン」は普通系で単為結果性を持つので、コバチによる受粉がなくても結実する。",
      "オ": "カンキツ類の中には、1種子内に受精胚と複数の珠心胚を持つ多胚性の品種がある。珠心胚は、減数分裂を経ない配偶体から作られる。受精胚は珠心胚よりも旺盛に成長し、珠心胚の発育を抑制する。"
