    "question": "次は、多収性の改良に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n多収性は作物育種の歴史の中で常に重要な育種目標となっており、収量を決める要因として収量構成要素、光合成能、草型、難脱粒性・難裂莢性等がある。1960年代から始まった「緑の革命」は、［A］の改良により飛躍的に収量性を伸ばした事例である。\n\nコムギではN. E. Borlaugらがメキシコの品種に我が国の栽培品種「［B］」が持つ遺伝子［C］を導入して多収品種を育成し、世界各地に普及させた。イネではH. M. Beachellらによって、インドネシアの品種に台湾の品種「低脚烏尖」が持つ遺伝子［D］が導入され、ミラクルライスと呼ばれる「［E］」が育成された。［C］はジベレリン情報伝達因子であるDELLAタンパク質をコードし、その機能の欠損により情報伝達の抑制が生じる。［D］はジベレリン生合成系のGA20酸化酵素をコードしており、その機能の欠損によりジベレリン合成量の低下をもたらす。いずれもジベレリンが持つ生理作用の変化を通じて収量の画期的な向上を可能とし、緑の革命に大きく貢献した。",
