    "question": "植物病原菌の病原性に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　病原糸状菌の宿主への侵入方法には、自然開口部や傷口からの侵入、角皮侵入などがある。一方、病原細菌は植物の角皮を貫通することができず、気孔や水孔といった自然開口部や傷口から植物体内へ侵入する。侵入は、風雨などによる偶発的な場合もあるが、一般には鞭毛による自発的な運動が必要である。\nB　植物病原菌は、宿主植物の細胞壁の構成成分を分解する酵素を感染時に分泌することが知られている。多くの糸状菌では、クチナーゼ、ペクチナーゼ、カタラーゼが宿主植物への感染を進める上で重要な役割を持つ。一方、軟腐症状を引き起こす細菌では、クチナーゼによって宿主植物の激しい組織崩壊を引き起こす。\nC　一部の植物病原菌では、感染した宿主の生産するファイトアレキシンを代謝・解毒することが知られている。エンドウ根腐病菌の強病原性系統は、エンドウのファイトアレキシンであるピサチンを代謝・解毒するピサチン脱メチル化酵素を生産する機構を持ち、ピサチンに強い耐性を示す菌株は病原力が強い傾向にある。\nD　ナス科植物青枯病菌やダイズ茎疫病菌のような導管で増殖する細菌によって引き起こされる萎凋症状は、細菌が大量に生産して放出する根状菌糸束による導管閉塞が原因である。根状菌糸束はそのほかに、乾燥や熱からの菌体の保護や、植物に水浸状病斑を生じるといった作用を持つと考えられている。",
