    "difficulty": 3,
    "question": "肥料に関する記述A～Dと肥料の名称の組合せとして最も妥当なのはどれか。\n\nA　ガラスの原料となるソーダ灰の副産物として生産され、速効性の生理的酸性肥料である。硫化水素を発生させない無硫酸根肥料であり、老朽化水田の窒素肥料として用いられる。\nB　カーバイドに窒素ガスを反応させて製造されるアルカリ性肥料である。成分中のシアナミドには殺虫、殺菌、除草効果があり、農薬としても登録されている。\nC　リン鉱石に蛇紋岩などを混合し、加熱融解した後に急冷することで製造されるアルカリ性肥料である。含有リン酸の98％以上が「く溶性」で、水には溶けにくく、緩効性である。\nD　原料は石灰石であり、主成分はCa(OH)₂である。土壌の酸性を矯正するために施用され、土壌消毒や除草効果もある。長く放置するとCO₂を吸収して炭酸石灰に変化する。",
