    "difficulty": 3,
    "question": "横断面（クロスセクション）データを用いて、農産物Aの需要関数を推定し、以下の結果を得た。\n\nlog Xₐ = β̂₀ ＋ β̂₁ log Pₐ ＋ β̂₂ log Pᵦ ＋ β̂₃ log Y\nXₐ：農産物Aの需要量（kg）、Pₐ：農産物Aの価格（円／kg）、Pᵦ：農産物Bの価格（円／kg）、Y：家計所得（万円）、logは自然対数を表す。\n\n農産物Aに関する「需要の価格弾力性」、「需要の交差弾力性」、「需要の所得弾力性」はそれぞれ、β̂₁、β̂₂、β̂₃として推定される。弾力性の符号や大きさから読み取ることのできる農産物Aと農産物Bの特徴について、以下のア～エに当てはまるものの組合せとして最も妥当なのはどれか。\n\nβ̂₁の絶対値が1より大きいとき、農産物Aは自己の価格に対して［ア］であり、価格の変化率よりも需要量の変化率の方が［イ］。β̂₂の符号が正であるとき、農産物Aは農産物Bの［ウ］である。また、β̂₃の符号が正のとき、農産物Aは［エ］であるといわれる。",
