    "difficulty": 3,
    "question": "情報の非対称性（非対称情報）などに関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　情報の非対称性（非対称情報）があるときに生じる問題として、「モラル・ハザードの問題」と「逆淘汰（逆選択）の問題」がある。直接観察できない隠された行動がある場合を「モラル・ハザードの問題」と呼び、隠された情報がある場合を「逆淘汰（逆選択）の問題」と呼ぶ。\nB　情報を持たない側が情報を持つ側に私的情報を開示させようとする方法をシグナリングと呼ぶ。例えば、保険会社が異なるタイプの複数の保険契約を提示し、その中から相手に選択させることにより契約者のサーチコストを下げるケースが挙げられる。\nC　リスク回避者とリスク中立的な者の間では、リスク中立的な者が全てのリスクを引き受けるのがパレート効率的である。このような例として、保険がある。保険会社は、大きな資産と多数の保険契約者や株主を持ち、リスクを分担する能力が高いため、ほぼリスク中立的である。\nD　事業者が相互に連絡を取り合い、本来、各事業者が自主的に決めるべき商品の価格や販売・生産数量などを共同で取り決める行為であるコングロマリットには、常に自分だけが抜け駆けをして得をしようという裏切りの誘惑がついてまわる。この関係は高い利潤を得られることで維持されている。",
