    "question": "経済成長と食料・農業に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　家計の食料費に占める主食への支出割合をエンゲル係数という。経済成長とともに食の多様化が進むと、主食への支出割合が低下するため、エンゲル係数は一般に小さくなる。このような経験則は、エンゲルの法則と呼ばれている。\nB　18世紀イギリスの経済学者であるマルサスは、「算術級数（等差数列）的に増加する人口と、幾何級数（等比数列）的に増加する食料生産の差によって、人口過剰つまり貧困が発生する。」とする命題を提唱した。\nC　経済成長の過程で、農業部門から非農業部門へ労働力がうまく移動せず、過剰な労働人口が農業部門にとどまる状態のことを農業の過剰就業という。我が国では、第二次世界大戦後すぐに農業の過剰就業は解消され、当時から農業労働力の確保が課題となっている。\nD　国民経済に占める割合の大きな産業部門は、経済成長とともに、農業を中心とする第一次産業から製造業を中心とする第二次産業へ、さらに商業を中心とする第三次産業へとシフトしていく。このような経験則は、ペティ・クラークの法則と呼ばれている。",
