    "question": "ある財の需要曲線と限界費用曲線はともに線形であり、D：需要量、p：価格、MC：限界費用とする。需要曲線はp = 10のときD = 30、p = 20のときD = 20、限界費用はMC = 10で一定とし、市場は競争的であるとする。また、この財の生産時に引き起こされる環境汚染により、生産1単位につき5の負の外部性が発生している。この財の供給を市場の自由な取引に委ねた場合の総余剰として最も妥当なのはどれか。",
