      "イ": "バリュー・チェーン（価値連鎖）は、P.コトラーが提唱したフレームワークである。これは、企業活動を人事・労務管理、技術開発、調達、インフラといった主活動と、購買物流、製造、出荷物流、販売・マーケティング、サービスといった支援活動に分けて、各業務の最終的な付加価値への貢献を鳥瞰する。これにより、個々の経営が持つ競争優位を表すことができる。",
