      "オ": "M. E. ポーターは、業界構造の分析の手法として、ファイブ・フォース分析を提唱した。この分析では、既存企業間の対抗度、買い手の交渉力、代替品の脅威、マスメディアの影響力、政府による干渉という五つの競争要因（five forces）から検討する。"
