      "ア": "製品ライフサイクルは、製品が市場に導入されてから衰退するまでの過程を示したもので、特定時点でどの段階にあるかを明確に判断することが可能である。縦軸に市場の成長率を、横軸に製品の市場シェアを記載した図で示される。",
      "イ": "導入期は、製品の市場規模が小さいが、競合企業が少ないため、利益は比較的大きい。導入期の顧客は、革新的採用者（イノベーター）である。革新的採用者は、高価格でも新製品や珍しいものを求めるため、企業は専ら浸透価格政策を採用する。",
