    "difficulty": 3,
    "question": "スマート農業技術に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年度 食料・農業・農村白書（令和6年5月31日公表）」による。\n\nA　生産現場においては、ロボットトラクターやスマートフォンで操作する水田の水管理システム等の活用により、農作業を自動化・省力化する取組が進められている。また、位置情報と連動した営農管理システムの活用により作業記録のデジタル化・自動化が可能となっている。\nB　令和元（2019）年度から農林水産省が開始した「スマート農業実証プロジェクト」（以下、実証プロジェクト）の結果、スマート農業技術の導入効果として、農業機械の自動運転や遠隔操作による労働時間の削減、環境・生産データを活用した栽培管理による収量・品質の向上や化学農薬・化学肥料の削減等が様々な品目で確認されている。\nC　実証プロジェクトの結果より、農業技術の導入効果を品目別にみると、水田作では各農場の平均で、総労働時間が約5割削減し、単収が倍増する。また、技術別にみると、農薬散布用ドローンで平均6％、自動水管理システムで平均8％、直進アシスト田植機で平均2％の作業時間の短縮を図れること等が明らかになっている。\nD　実証プロジェクト等を通じて、スマート農業の実装に当たっての課題も判明しており、例えば、スマート農業機械の導入コストが高いことや扱える人材が不足していることが挙げられる。このほか、果樹や野菜の収穫等といった人手に頼っている作物では、スマート農業技術の開発が不十分な領域があることも判明している。",
    "choices": {
      "ア": "A、B",
      "イ": "B、C",
      "ウ": "C、D",
      "エ": "A、B、D",
      "オ": "A、C、D"
    },
