    "difficulty": 3,
    "question": "令和6（2024）年に食料・農業・農村基本法が改正されたが、同法が制定された頃と比べた際の情勢変化に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和5年度 食料・農業・農村白書（令和6年5月31日公表）」による。\n\nA　我が国は、平成10（1998）年に世界の農林水産物純輸入額に占めるシェアが約4割と世界最大の農林水産物純輸入国であり、令和3（2021）年時点においても引き続き世界最大の農林水産物純輸入国であるものの、シェアは約3割に低下した。この間、中国のシェアが大きく伸びたが、広大な国土で生産される米や小麦の輸入はほとんど行われていない。\nB　我が国の食品産業においては、環境や人権に配慮して生産された輸入原材料の使用や食品ロスの削減といった持続可能性の確保に向けた取組が求められるようになってきている。このような取組の例として、一部のプランテーションにおける強制労働や児童労働といった労働者の人権への配慮などが挙げられる。\nC　我が国では、基幹的農業従事者数が平成12（2000）年から令和5（2023）年にかけて半減し、年齢構成のピークが70歳以上層となるなど農業者の減少・高齢化が進行する中、離農した経営体の農地の受け皿となってきた規模の大きい経営体が増加している。\nD　我が国の農村では都市に先駆けて人口減少・過疎化が進んできた。このような農村の人口減少は、これまで、自然減を主として想定しており社会減と比べて大きかったが、近年では逆転し、社会減の方が大きくなっている。農業地域類型別の人口構成の変化を見ると、平成12年と令和2（2020）年を比較して、人口減少率は平地農業地域の方が山間農業地域よりも高い。",
