    "question": "農業生産資材に関する記述として最も妥当なのはどれか。なお、データは「令和5年度 食料・農業・農村白書（令和6年5月31日公表）」による。",
    "choices": {
      "ア": "農業生産資材価格指数（光熱動力）は、令和3（2021）年以降上昇傾向で推移しており、我が国の施設園芸経営では、令和4（2022）年の経営費に占める燃料費の割合が約6割となった。燃油価格の影響を抑えるため、省エネルギーであるハイブリッド型園芸施設への転換が進められ、加温設備を備えた温室の大部分にヒートポンプが導入されている。",
      "イ": "配合飼料の原料使用量のうち5割を占めるとうもろこしの国際相場は、バイオエタノール向け需要の拡大や主要輸出国における輸出規制、ロシアによるウクライナ侵略を背景に、高い水準で推移している。耕種農家と畜産農家が連携し、飼料作物と堆肥を循環させるリサイクルループの取組について、その重要性が一層高まっている。",
      "ウ": "食品関連事業者（食品製造業、食品卸売業、食品小売業、外食産業）から発生する食品循環資源の有効活用に向けた取組が進み、食品循環資源を堆肥化した肥料を利用して生産されたエコフィードの製造数量は令和4年までの直近5年間で増加した。令和4年におけるエコフィードの製造数量は濃厚飼料全体の約3割に相当する水準となっている。",
      "エ": "我が国では、肥料原料となる、尿素やりん酸アンモニウム、塩化加里の約6割を輸入している。令和4肥料年度において、りん酸アンモニウム、塩化加里のほぼ全量を豪州から輸入しており、特定国からの輸入に大きく依存していることから、輸入原料から国内資源への代替が必要である。",
      "オ": "下水汚泥はこれまで主に焼却灰として埋立てや建設資材等に活用され、令和4年時点で我が国の全汚泥発生量に占める肥料利用の割合は約1割である。輸入依存度の高い肥料原料の価格が高騰する中で、持続可能な食料システムの構築に向け、下水汚泥資源の活用に対する関心が高まっている。"
    },
