      "オ": "2022年時点の下水汚泥の肥料利用は約1割で、主な処理・利用には焼却灰の埋立てや建設資材としての活用があった。肥料原料の輸入依存を抑えるため、汚泥由来のリンなどの国内資源の利用が進められている。"
