    "difficulty": 3,
    "question": "次は、組換え価に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n組換え価は、組換えの程度を表す単位であり、ある一対の遺伝子座において組換えが起こる頻度と定義され、通常［A］％の値をとる。一般に、組換えは減数分裂の［B］に起こる。\nここで、ニワトリの短肢と鶏冠の遺伝子座を例に組換え価を求める。ニワトリにおけるバラ冠（遺伝子R）は単冠（r）に対して優性（顕性）、短肢（遺伝子C）は正常肢（c）に対して優性である。組換え価を求めるために、バラ冠・正常肢の系統（Rc／Rc）と単冠・短肢の系統（rC／rc）を交雑した後、バラ冠・単肢のF₁に単冠・正常肢の系統を交雑した。得られた次世代の遺伝子型の分布は表のようになった。\n\n両形質を支配する遺伝子が独立していた場合、得られた次世代における各遺伝子型の出現比は［C］と予想される。しかし、表の結果から両形質を支配する遺伝子は連鎖していると分かる。この場合、組換え価は約［D］％と求めることができる。",
