    "difficulty": 3,
    "question": "ゲノム育種とその手法に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　量的形質遺伝子座（QTL）の責任遺伝子はQTG、原因DNA変異はQTNと呼ばれる。QTL解析により絞り込んだ候補ゲノム領域から量的形質に関わる候補QTGを選出する方法として、一塩基多型（SNP）を用いたハプロタイプ解析や候補ゲノム領域のシークエンス解析などがある。\nB　候補QTN領域について、突然変異型のDNAと野生型のDNAを入れ替えた遺伝子改変動物を作製し、表現型の回復や突然変異型への誘発を調査することは、量的形質に関わる責任QTNの同定に有効といえる。家畜におけるQTNの同定は遺伝子アシスト選抜を可能とする。\nC　マーカーアシスト浸透交雑（MAI）では、標的遺伝子を保有するドナー種と、その導入をはかるレシピエント種との交雑種をドナー種に交配することを繰り返す。標的遺伝子のホモ接合体の選抜にDNAマーカーを利用するが、MAIでは標的遺伝子がポリジーンである必要がある。\nD　ゲノミック選抜は、全塩基配列の情報を利用して遺伝的能力評価を実施する方法であり、血統情報に基づく従来法と比較して評価の正確度が高い。国内では、乳用牛、肉用牛、ブタにおいてゲノミック選抜による種畜の造成が行われている。",
