      "イ": "家畜の毛色や家禽の羽色は、ケラチン生合成に関連する遺伝子によって制御されている。ウシにおいて、シャロレー種の白色は伴性、ショートホーン種の白色は顕性である。また、ニワトリにおいて、白色レグホン種の白色は伴性、白色ロック種の白色は顕性である。",
