      "オ": "ある形質に影響する異なる遺伝子座の遺伝子又は遺伝子型間での相互作用を、相加的遺伝子効果という。相加的遺伝子効果の総和を育種価といい、その推定には遺伝率や選抜効率といった遺伝的パラメーターが必要である。"
