    "difficulty": 3,
    "question": "次は、育種価に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n育種価は種畜としての遺伝的能力を判断する評価基準の一つである。ここでは個体自身の1回記録に基づいて育種価を算出する場合を考える。評価対象個体のある形質に対する表現型値がY、選抜対象としている集団平均がμ、表現型値に対する育種価の回帰係数である遺伝率がh²で与えられているとき、推定育種価は［A］と求められる。表現型値は［B］と環境偏差の和であり、遺伝率は［C］を［D］で除した値である。［E］法では、改良したい複数形質の遺伝的パラメーター及び経済的重み付け値に基づいて算出される総合育種価の推定値に基づいて選抜を行う。",
