    "difficulty": 3,
    "question": "遺伝子の構造と発現に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　DNA上にはmRNAへの転写を指示するキャップ配列や転写の終了を指示するターミネーターがある。また、mRNA上にある翻訳開始コドンから翻訳され、翻訳停止コドンまでタンパク質合成される。翻訳開始コドンは一種類であり、トリプトファンが対応している。翻訳停止コドンは三種類ある。\nB　スプライシングとは、転写生成物（mRNA前駆体）からイントロンを取り除きエキソンが連結して成熟mRNAが出来上がる過程を指し、真核生物のみでみられる仕組みである。選択的スプライシングはエキソン配列を選択的につなぎ合わせることで、タンパク質の多様性の創出に貢献している。\nC　DNAのアセチル化やヒストンのメチル化が生じた遺伝子は必ずインプリンティングを受ける。ある形質がインプリンティングを受けた遺伝子に支配されている場合、後代の表現型は両親両方の遺伝子の効果が相加的に表れる。\nD　DNAのヌクレオチドのうち、塩基の種類だけに着目し、並べたものを塩基配列と呼ぶ。この塩基配列が遺伝情報であり、個体ごとに一つ以上の塩基が欠損、挿入又は置換によって異なっているところが存在する。ある一定範囲の塩基配列の中で、一つの塩基が異なっている状態を一塩基多型と呼ぶ。",
