    "question": "次は、哺乳動物の生殖原基の形成及び性腺の性分化に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n哺乳動物において、精巣や卵巣の基となる生殖原基を構成する体細胞は［A］を起源として左右一対の生殖隆起として発達する。始原生殖細胞は［B］を経て生殖隆起へ移動するが、その際、ケモカインである［C］とその受容体が関与する。未分化な生殖原基は、形態的に雌雄差はない。その後、生殖細胞を支える支持細胞が、雄型の［D］又は雌型の顆粒層細胞へと分化する。また、［D］への分化にはSRYや［E］遺伝子が関与する。顆粒層細胞への分化に関与する因子として、FOXL2が知られているが、FOXL2は［E］を下方制御すると考えられている。",
