      "ア": "ウシにおいては、性判別胚の移植又は性選別精液の利用により、高精度な雌雄産み分けが可能である。ウシの胚の性判別では、PCR法やLAMP法によりY染色体に特異的なDNA配列の有無を調べる。ウシの精子の性選別では、一般にフローサイトメトリー法により、X精子でY精子より3.8％多いDNA量の差異を検出する。",
