      "オ": "オブシンク法は、ウシの過剰排卵処置法の一つであり、一般に発情周期の任意の時期にGnRH製剤を投与して排卵誘起と卵胞波のリセットを行う。GnRH製剤を投与して7日後にエストラジオール製剤を投与して黄体退行を誘起し、30～56時間後に再びGnRH製剤を投与することで排卵を誘起する。"
