    "question": "次は、鶏の産卵機構や産卵周期に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n産卵鶏の生殖器の形成過程では、卵巣と卵管の原基は腹腔内の左右に一対出現するが、形成途中で［A］側のみが発達を継続し、卵巣及び卵管を形成する。\n産卵鶏の卵巣には、微小な皮質卵胞や直径5 nm以下の白色卵胞、約5～35 nmの黄色卵胞が分布している。卵胞が成熟すると、［B］の一過性の上昇による刺激を受け、卵子が排卵される。卵巣から排卵された卵子は卵管漏斗部から卵管内に取り込まれる。卵子は卵黄部分となり、卵管内を下降する間に、卵黄の周囲に卵白、次いでその外側に卵殻膜が形成され、最後に卵殻が沈着する。鶏卵は卵管内で約［C］時間かけて完成卵となる。\n産卵鶏の卵巣と卵管が病原微生物に感染すると、卵形成の異常や産卵された卵の微生物汚染が生じる。それを防ぐための免疫機能として、卵巣と卵管にはマクロファージやキラーT細胞、B細胞などが存在する。また、移行抗体がヒナの初期感染防御に貢献している。ここでの主要な抗体は［D］で、母鶏の血中から［E］へ移行する。",
