    "question": "次は、乳牛における泌乳調節に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n栄養素は、成長期には骨・筋肉などの体成長に、妊娠中は胎子の成長に、泌乳期では乳腺における乳合成に優先的に使われる。このように特定の生理反応を強化する現象は［A］と定義される。成長ホルモン（GH）は［B］とも呼ばれ、視床下部から分泌されるGH放出ホルモン及びソマトスタチンは下垂体前葉に作用してGHの分泌を調節する。GHは肝臓に作用して［C］の分泌を促進する。そして、［C］が乳腺に作用して最終的に乳汁の産生へとつながる［B］軸を形成する。GHは、筋肉や脂肪組織における［D］抵抗性を増強させ、グルコースの体成長やエネルギー貯蔵への利用を［E］する。すると、［D］非依存的に大量のグルコースを細胞内に取り込むことができる乳腺に、乳糖合成の基質であるグルコースを優先的に配分することができる。",
