    "difficulty": 3,
    "question": "次は、骨格筋の成長に関する記述であるが、ア～オに当てはまるものの組合せとして最も妥当なのはどれか。ただし、解答に使用する語句は文脈に応じて斜体となるものとする。\n\nA muscle can grow in three ways: its fibers can increase in number, in length, or in girth. Because skeletal muscle fibers are unable to divide, more of them can be made only by the fusion of ［ア］, and the adult number of multinucleated skeletal muscle fibers is in fact attained early — before birth, in humans. Once formed, a skeletal muscle fiber generally survives for the entire lifetime of the animal. However, individual muscle ［イ］ can be added or lost. The enormous postnatal increase in muscle bulk is achieved by cell enlargement.\n\n（中略）\n\nWhat, then, are the mechanisms that control muscle cell numbers and muscle cell size? One part of the answer lies in an extracellular signal protein called ［ウ］. Mice with a ［エ］-of-function mutation in the ［ウ］ gene have enormous muscles — two to three times larger than normal. Both the numbers and the size of the muscle cells seem to be increased. Mutations in the same gene are present in so-called “double-muscled” breeds of cattle.\n\n（中略）\n\nIt is normally made and secreted by skeletal muscle cells, and it acts powerfully on ［ア］, inhibiting both proliferation and differentiation. Its function, evidently, is to provide ［オ］ feedback to limit muscle growth, in adult life as well as during development.",
