    "explanation": "第一胃の発酵で生じる短鎖脂肪酸は通常酢酸が最も多く、唾液が弱酸性から中性付近のpHを保つ。余剰アンモニアは第一胃壁から吸収され、炭素数18の不飽和脂肪酸の水素添加産物はステアリン酸である。",
