      "ウ": "「家畜伝染病予防法」は、平成30（2018）年度に国内で大幅に発生件数が増加した高病原性鳥インフルエンザ、アジア地域において急速に発生が拡大していたCSF（豚熱）に対応するため、令和2年に法改正が行われた。CSFについては、国や都道府県などの責任が明確化され、予防的殺処分の対象疾病に追加された。",
