    "question": "我が国の水産資源の管理に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　水産庁は、令和6（2024）年3月に「資源管理の推進のための新たなロードマップ」を策定・公表した。そこでは、令和12（2030）年度に444万トンまで漁獲量を回復させることを目標とし、取組として、MSY＊1ベースの資源評価対象資源を現在の38資源から150資源程度に拡大することや、令和7（2025）年度までに漁獲金額ベースで8割の資源でTAC＊2管理を開始すること等が記載されている。\nB　TACによる管理を行う資源は、特定水産資源として定められ、それぞれ、資源評価に基づき、目標管理基準値や限界管理基準値等の資源管理の目標を設定し、その目標を達成するようあらかじめ定めておく漁獲シナリオに則してMSYが決定される。そして、目標管理基準値を下回った場合には、同基準値まで回復させるための計画を定めて実行することとされている。\nC　TAC資源拡大に向けた検討状況として、令和6年3月末時点で、22種38資源について、MSYベースの資源評価結果が公表され、20種34資源について、資源管理手法検討部会が開催され、5種11資源について、ステークホルダー会合が開催された。このうち、カタクチイワシ及びウルメイワシ対馬暖流系群は、水産政策審議会資源管理分科会への諮問を経て、令和6年1月からTAC管理が開始された。\nD　資源管理協定を策定する際には、資源評価対象種については、資源評価結果に基づき資源管理の目標を設定すること、資源評価が未実施のものについては、利用可能な最善の科学情報を用いて資源管理の目標を設定することとしている。同協定は、農林水産大臣又は都道府県知事が認定・公表する。\n\n＊1 最大持続生産量\n＊2 漁獲可能量",
