    "question": "漁業就業や労働環境の動向に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和5年度 水産白書（令和6年6月11日公表）」による。\n\nA　現行の技能実習制度は、人材育成を通じた国際貢献を制度目的としており、労働力の需給調整の手段として行われてはならないという基本理念が掲げられている。水産業における外国人技能実習としては、漁船漁業・養殖業における10種の作業及び水産加工食品製造業・水産練り製品製造業における10種の作業について実施されている。\nB　平成31（2019）年4月以降、在留資格「特定技能」での外国人の受入れが始まっており、令和5（2023）年12月末時点で、漁業分野（漁業、養殖業）の特定技能1号在留外国人数は4,000人を超えている。本制度では、全ての漁業・養殖業への従事が可能であり、業務区分間の転職・転籍ができる。\nC　令和5年の漁船の船舶事故隻数は、平成25（2013）年の約1.5倍に増加している。特に、5トン未満の小型漁船は大型船からの視認性が悪いなど、事故のリスクを抱えていることを踏まえ、漁船を含む全ての船舶に対して、船舶の位置、針路、速力等の航行情報を相互に交換できるAIS＊の設置が義務付けられている。\nD　令和5年のデータでは、漁業者の海中転落時のライフジャケット着用者の生存率は、非着用者の生存率の2倍以上となっている。平成30（2018）年2月以降、船舶職員及び小型船舶操縦者法に基づき、原則として、船室の外にいる全ての乗船者にライフジャケットの着用が義務付けられており、令和4（2022）年からは、違反した場合は船長に対して違反点数が付与されることとなった。\n\n＊ Automatic Identification System",
