    "question": "次は、我が国における水産物の需給に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。なお、データは「令和5年度 水産白書（令和6年6月11日公表）」による。\n\n我が国の食用魚介類の自給率は、昭和39（1964）年度の113％をピークに低下傾向で推移している。令和4（2022）年度における食用魚介類の自給率（概算値）は［A］％であり、平成24（2012）年度と比較して同程度であったが、令和4年度の国内消費仕向量は、平成24年度と比較して約［B］割減少している。\n国内消費仕向量は主に国内生産量、輸出量及び輸入量により算出され、このうち平成24年度と比較して令和4年度に増加しているのは［C］である。\n食用国内消費仕向量を構成する「生鮮・冷凍」及び「加工品」について、平成24年度と比較した令和4年度の減少率が大きかったのは［D］である。\n非食用国内消費仕向量のうち、養殖用配合飼料の主原料である魚粉は、輸入に大きく依存している。近年、最大の魚粉生産国である［E］におけるアンチョペータの不漁等により、輸入価格は上昇傾向で推移している。",
