    "difficulty": 3,
    "question": "次は、2001年に国際連合食糧農業機関（FAO）で採択された「違法、無報告、無規制（IUU）漁業を防止、抑止、排除するための国際行動計画（IPOA）」の一部を抜粋したものであるが、ア～エに当てはまるものの組合せとして最も妥当なのはどれか。\n\nParticipation and coordination: To be fully effective, the IPOA should be implemented by all States either directly, in cooperation with other States, or indirectly through relevant ［ア］ fisheries management organizations or through FAO and other appropriate international organizations. An important element in successful implementation will be close and effective coordination and consultation, and the sharing of information to reduce the incidence of IUU fishing, among States and relevant regional and global organizations. The full participation of stakeholders in combating IUU fishing, including ［イ］, fishing communities, and non-governmental organizations, should be encouraged.\n\n（中略）\n\nComprehensive and integrated approach: Measures to prevent, deter and eliminate IUU fishing should address factors affecting all capture fisheries. In taking such an approach, States should embrace measures building on the primary responsibility of the flag State and using all available jurisdiction in accordance with ［ウ］ law, including port State measures, coastal State measures, market-related measures and measures to ensure that nationals do not support or engage in IUU fishing. States are ［エ］ to use all these measures, where appropriate, and to cooperate in order to ensure that measures are applied in an integrated manner. The action plan should address all economic, social and environmental impacts of IUU fishing.",
