      "エ": "死亡のみで年級群の個体数は減る。定数Qをもつ一次微分方程式を解くと指数はQtとなり、Qt²にはならない。",
      "オ": "指数をQt²にすると微分した際の係数が時間とともに変化する。式（1）の定数Qで死亡を表すと、個体数は減少し、1単位時間の生残率はexp(Q)になる。"
