      "エ": "ある栄養段階における年間生産量（P）と生物量（B）の比（P/B比）を生態効率と呼ぶ。単位面積当たりの一次生産者の生物量を比較すると海洋は陸上の約10分の1であるが、一次生産者のP/B比を比較すると海洋は陸上の約300倍高い値を示す。",
