    "explanation": "理想化したエクマンモデルでは北半球の表層流が風下方向から右へ45度、深さ方向に積分した輸送が右へ90度ずれる。北太平洋は亜寒帯循環の中央付近で発散・湧昇し、亜熱帯循環の中央付近で収束・沈降する。",
