    "difficulty": 3,
    "question": "海洋プラスチックごみに関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　我が国では令和元（2019）年5月に「海洋プラスチックごみ対策アクションプラン」が策定されたほか、令和3（2021）年6月にプラスチックに係る資源循環の促進等に関する法律が成立するなど、海に流出するプラスチックごみの増加の問題の解決へ向けた取組が行われている。\nB　海洋におけるプラスチックごみは、海洋生物による誤食、海洋生物が投棄・遺失漁具に絡まり死亡するゴーストフィッシング、海岸の自然景観の劣化など、環境や生態系へ影響を与えている。さらに、漁業に対しても、プラスチックごみが漁獲物に混入したり、漁船のスクリューに絡まったりするなどの影響を与えている。\nC　マイクロプラスチックは、プラスチックごみが赤外線等による劣化や破砕・細分化のプロセスを経て発生する。マイクロプラスチックはサイズが小さく沈降しないため、これらが環境や生態系に影響を与えている範囲は、海洋の表層に限定されている。\nD　水産庁は令和2（2020）年に「漁業系廃棄物計画的処理推進指針」を策定した。そこでは、生分解性プラスチック等を用いた漁具開発・改良や、漁網等のリサイクル推進等の支援を行うほか、漁業者による海洋ごみの持ち帰りの促進などを行うこととしている。",
