    "difficulty": 3,
    "question": "水生生物の循環器、呼吸器及び血液に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　魚類の心臓は囲心腔に位置し、一心房一心室の構造をとる。一般に硬骨魚類では動脈球、軟骨魚類では心臓球が発達する。血液中に赤血球が占める相対容積をヘマトクリット値と呼び、魚類では通常10～40％程度である。\nB　魚類の赤血球は哺乳類と同様に無核である。魚類の呼吸色素はヘモグロビンであり、ヘモグロビン1分子に対し酸素を最大で5分子結合することができる。ヘモグロビンの酸素飽和度が高くなったときに、血液中に含まれる二酸化炭素量が低下する効果をルート効果と呼ぶ。\nC　頭足類は一般に開放血管系を持つ。頭足類では呼吸色素としてヘモシアニンがみられる。ヘモシアニンには鉄が含まれ、酸素を失うと青色を呈し、酸素と結合すると無色になる。頭足類は普通の心臓のほかに一対の鰓心臓を持つ。\nD　魚類の主要な呼吸器である鰓において、鰓弁は鰓弓の外側に二列に並ぶ。各鰓弁には両側に突出する二次鰓弁がみられる。二次鰓弁内部の血液と、二次鰓弁表面の水が逆方向に流れることにより、効率よくガス交換を行う仕組みを対向流系と呼ぶ。",
