    "question": "魚類の栄養要求に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　魚類ではヒトと同じく、フェニルアラニンやトリプトファンをはじめとした計8種類のアミノ酸が必須アミノ酸とされている。これらのアミノ酸に加えて、淡水魚のみが、タウリンを必須アミノ酸のように要求することが知られている。\nB　一部の魚種では、脂質を用いて飼料中の可消化エネルギー含有量を増加させることにより、飼料中のタンパク質適正量を減らすことができる。これを脂質によるタンパク質節約効果と呼ぶ。飼料中の脂質はエネルギーのみならず、必須脂肪酸の供給源でもあり、マダイでは必須脂肪酸としてドコサヘキサエン酸などのn-3系高度不飽和脂肪酸を要求する。\nC　飼料中における炭水化物の至適添加量は魚種によって異なり、マダイでは40～50％程度であるが、肉食傾向の強いブリでは20％程度である。ニジマスでは単糖類よりも多糖類の方が高い消化率を示す。さらに、ニジマスでは生デンプンの方が加熱処理により糊化したデンプンよりも消化されやすい。\nD　魚種によって飼料に要求するミネラルは異なるが、カルシウムは環境水中にほとんど含まれていないため、ほぼ全ての魚種で飼料中に要求する。ミネラルの吸収率は有胃魚と無胃魚で大きく異なり、無胃魚であるコイは難溶性の第三リン酸カルシウム中のリンを効率的に利用できる。",
