    "question": "魚病に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　冷水病は、グラム陰性細菌Flavobacterium psychrophilumによる疾病で、我が国ではサケ科魚類やアユで問題となっている。ワクチンに関しては有効性が示されているものの、令和6（2024）年3月末時点で、我が国では実用化されていない。\nB　伝染性造血器壊死症は、主にマダイにみられる感染症であり、本症に罹患すると体表面に瘤状の隆起が認められる。本症はInfectious pancreatic necrosisウイルスに由来する。本ウイルスは成魚に対して高い致死率を示すが、稚魚には感染しない。\nC　連鎖球菌症には病原体が異なるα溶血性とβ溶血性の2種類がある。前者は主にブリ類にみられる疾病で、グラム陽性菌Lactococcus garvieaeに起因する。後者はグラム陽性菌Streptococcus iniaeによるもので、ブリ類以外にもヒラメ、アジ、サバなど様々な魚種が罹患する。\nD　せっそう病は、主にウナギにみられる感染症であり、本症に罹患すると体表に特徴的なV字型の出血が認められる。病原体は微胞子虫Heterosporis anguillarumであり、微胞子虫が産生する酵素によって体表の出血が生じる。",
