      "イ": "生殖腺では性ホルモンをはじめとして様々なホルモンが産生される。魚類の卵巣で産生される代表的な雌性ホルモンとして11-ケトテストステロン（11-KT）が知られ、これは卵母細胞に作用して卵黄タンパク質前駆体であるビテロジェニンの合成を促進する。",
