    "difficulty": 3,
    "question": "我が国の養殖場における餌飼料に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　ワムシは、輪形動物門に属する動物プランクトンで、大量培養が可能なため仔魚の初期餌料として有用である。一方でエイコサペンタエン酸やドコサヘキサエン酸などの高度不飽和脂肪酸が不足しているため、これらの脂肪酸を要求する魚種に与える場合には、栄養を強化する必要がある。\nB　アルテミアは、ブラインシュリンプとも呼ばれる甲殻類で、マダイやヒラメなどの種苗生産の餌料系列ではワムシよりも小型の餌料生物として汎用される。生活史の中で形成するシストが製品化されており、これから孵化する幼生が飼料に用いられる。ワムシと比較して高度不飽和脂肪酸を豊富に含むため、栄養強化は不要である。\nC　エクストルーディッド・ペレット（EP）は、高温・高圧下で成型し乾燥させた配合飼料である。EPは多孔質であり、その孔に水分が浸透して脂質含有量が低くなることから、脂身の少ない魚を育てることが可能である。一方で浮力に乏しく、沈降性の餌しか製造できないという欠点もある。\nD　ドライペレット（DP）は、粉末原料と油脂を混合してペレットミルという装置で成型した円柱状の配合飼料である。DPは、脂質含有量が高いため冷蔵で保存する必要があるが、EPに比べて栄養価が高く、沈降性の調整が可能である。",
