    "officialAnswerNumber": 1,
    "explanation": "小型のワムシは大量培養しやすく、仔魚が捕食できる初期餌料になる。海産仔魚に必要なEPAやDHAが不足する場合は、給餌前にこれらの栄養分を強化する。",
