    "question": "水産物の変色に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　タイ・キチジ・メヌケ類などの魚皮の赤色は、セラミド系のアスタキサンチンによるものであり、冷凍保存中に退色することがある。これは、低温耐性がある加水分解酵素により、アスタキサンチンが灰色の化合物に変化するためである。\nB　冷凍保存したエビ・カニ類では、凍結解凍により黒色化が進行することがある。これは、甲殻類に含まれるチロシンや3,4-ジヒドロキシフェニルアラニンにフェノール酸化酵素が作用し、黒色色素のメラニンが生成されるためである。\nC　緩慢凍結したカツオ肉を原料としたカツオの缶詰では、開缶後に空気との接触で褐色に変色し、焦臭を発生することがある。これは、解糖系の最終産物が、自己消化酵素によって生成したアミノ酸とメイラード反応を起こすためである。\nD　高鮮度な状態で急速凍結したカジキ肉には、解凍後に淡青色や緑色を呈するグリーンミート（緑変）と呼ばれる現象が起こることがある。これは、カジキ肉中に含まれているヘモシアニンとトリメチルアミンオキシドが反応を起こすためである。",
    "choices": {
      "ア": "A",
      "イ": "B",
      "ウ": "A、C",
      "エ": "B、D",
      "オ": "C、D"
    },
    "answer": "イ",
    "officialAnswerNumber": 2,
    "explanation": "エビやカニではフェノール酸化酵素がチロシンなどからキノン類を生じさせ、反応が進むとメラニンが生成される。この酵素的な黒変は凍結解凍の過程でも進み得る。",
    "choiceExplanations": {
      "ア": "アスタキサンチンはカロテノイドの一種である。冷凍中の退色には酸化などが関わり、加水分解による灰色の化合物の生成という説明は妥当でない。",
      "イ": "エビやカニではフェノール酸化酵素がチロシンなどからキノン類を生じさせ、反応が進むとメラニンが生成される。この酵素的な黒変は凍結解凍の過程でも進み得る。",
      "ウ": "Aはアスタキサンチンの分類を誤っている。Cの缶詰の変色にはグルコース6-リン酸などが関与する加熱時の反応が知られ、開缶後に反応が始まるという説明は妥当でない。",
      "エ": "Bのメラニン生成は妥当である。Dのカジキの緑変にはヘム色素の変化が関わり、カジキの筋肉にヘモシアニンがあるという前提を欠く。",
      "オ": "Cは缶詰加工と開缶後の変化を取り違えている。Dに挙がるヘモシアニンは一部の無脊椎動物の酸素運搬タンパク質である。"
    },
