    "question": "水生生物の色素に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　エビやカニなどの甲殻類に存在するアスタキサンチンは、クラスタシアニンというタンパク質と結合することで青色から紫色、黄色を呈する。しかし、加熱などによりクラスタシアニンが変性すると、アスタキサンチンの元の色である赤色を呈する。\nB　ミオグロビンは、魚類の心筋や血合筋に高濃度で存在する分子量約7万の繊維状タンパク質であり、1分子当たり1分子のヘムを含み分子状酸素と結合する。還元型ミオグロビンは鮮赤色を呈するが、ヘムに酸素が結合しオキシ型になると暗赤紫色を呈する。ミオグロビンは水によく溶けるためにドリップ中に溶出しやすい。\nC　クロロフィルは、マグネシウムと配位した脂溶性の金属ポルフィリン色素である。クロロフィルは、クロロフィルa、b、cなどに分けられ、緑藻はaとbを、褐藻はaとcを持つ。褐藻はさらにカロテノイドであるフコキサンチンを持ち、その総含量がクロロフィルに比べて高いためクロロフィルの緑色がフコキサンチンの橙色にマスクされて褐色に見える。\nD　紅藻やラン藻は、クロロフィルを持たない代わりに、フィコエリトリン、フィコシアニン、及びアロフィコシアニンなどの光合成色素タンパク質を持っている。これらの集光色素部分はフィコビリンと呼ばれ、システイン残基を介してタンパク質部分とイオン結合している。",
