    "question": "魚類の回遊と生活史に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　海と河川を行き来する魚を通し回遊魚と呼ぶ。一般に、通し回遊魚は、産卵のために河川を上る遡河回遊魚、逆に産卵のために河川を下る降河回遊魚、及び海と河川の両方で産卵する両側回遊魚の三つに定義される。このうち代表的な両側回遊魚として、チョウザメやカワヤツメが挙げられる。\nB　遡河回遊魚であるサクラマスの稚魚はスモルトと呼ばれ、河川で1～2年成長する。やがて性的に成熟すると体色が黒色に変化し、海へと下る。この体色の変化は皮膚へのメラニンの沈着によるものであり、甲状腺から産生されるメラニン凝集ホルモンにより誘起される。サクラマスには陸封型の個体群が存在し、これをイワナと呼ぶ。\nC　降河回遊魚であるニホンウナギは、マリアナ諸島西方海域で産卵するといわれている。ここで生まれた仔魚はレプトセファルス幼生となって海流に乗り、東アジア近海域へと輸送される。そしてシラスウナギへと変態した後、河川へ遡上して黄ウナギとなる。性成熟が始まると銀ウナギへとなり、海へと下る。近年、一生を海で過ごす海ウナギも発見された。\nD　遡河回遊魚であるアユは、秋に河川の中・下流域で生まれ、仔アユは河川の流れに乗って沿岸域に到達し、そこで稚アユとなる。3～4年後の春になるとアユは河川を遡上し、甲殻類や小型魚を食べてさらに成長する。やがて秋になると河川の産卵場に移動して繁殖した後、一旦沿岸域に下り、翌年再び繁殖のため河川を遡上する。",
