    "question": "次は、コロナ禍における缶詰食品と食品ロスについて書かれた記事からの抜粋であるが、ア～エに当てはまるものの組合せとして最も妥当なのはどれか。\n\nCanned fish is consumed all over the world and is assumed to be associated with fairly low levels of food loss and waste. Fish is usually canned in small servings; thus, ［ア］ control is already factored in already. Waste associated with processing will more than likely have been dealt with at the canning stage, when trimmings and other ［イ］ are converted into other products such as fish meal. Furthermore, canned fish is a very shelf-stable product and can remain in storage, without the need for temperature control, for long periods of time, thus loss and waste due to perishability is minimal.\n\n（中略）\n\nCanned fish such as sardines and ［ウ］ are rich in protein and omega-3 fatty acids and a range of vitamins and minerals. Canned fish is a good source of nutrients, important for health and supporting people’s immune system. It is an option when fresh or other fish products are not available. So it is not surprising then that canned fish is one of the World Health Organization’s (WHO) recommended foods for quarantine and self-isolation during the COVID-19 pandemic.\n\nIn fact, several large producers of canned fish have seen sales ［エ］ as a result of consumers preparing for, or going through, COVID-19 lockdown. This could all bode well for the future demand for a product that is associated with minimal food loss and waste.",
