      "ウ": "by-productsとmackerelは文脈に合う。ロックダウンの備蓄で需要が増え、今後の需要にも好材料だと続くので、売上の変化はincreaseである。",
      "エ": "portionとby-productsは合うが、バッタを指すlocustは魚の例として適さない。売上の動きもdecreaseではなくincreaseである。",
