    "question": "水産加工品に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　かつお節の原料となるカツオは、日本近海で漁獲されるもののほか、海外で漁獲され、エアブラスト凍結されたものも一般に使用されている。カツオの脂肪含量は製品の品質を左右し、脂肪含量の少ない原料を使用した製品は香味が劣り、貯蔵中に変色しやすい。焙乾の終わった節は表面が燻製のタール質で覆われて黒褐色を呈していることから、本枯節と呼ばれる。\nB　魚醤は、魚介類に食塩を加えて防腐しながら自己消化酵素と微生物の作用により熟成させ、分離した液体部分を加熱、ろ過したものである。秋田県で生産されるしょっつるは、原料となるハタハタ、イワシなどに食塩を加えて、1年以上の時間をかけて熟成させる。その主な成分は、魚介類のタンパク質が分解されたアミノ酸やペプチドである。\nC　スケトウダラの卵巣は、その熟度によって、がむ子、真子、目付け、水子に分けられ、その塩蔵品をたらこと呼ぶ。鮮度が低下した卵巣は、肝臓から浸出した油によって、濃緑色に着色する場合がある。たらこの変色を防止するための発色剤としては、酢酸ナトリウムが用いられている。\nD　まぐろ・かつお缶詰は水煮、油漬け、味付けの三つに大別され、その原料には、主にライトミートといわれるキハダ、メバチ、カツオや、ホワイトミートといわれるビンナガが使われる。令和5（2023）年におけるまぐろ・かつお缶詰の生産量は、さば缶詰の生産量を上回り、我が国で生産される水産缶詰のうち最も生産量が多かった。",
